from collections import deque,defaultdict
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==9 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c));cells=[]
  while q:
   x,y=q.pop();cells.append((x,y))
   for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
    if 0<=a<R and 0<=b<C and (a,b) not in seen and grid[a][b]==col:
     seen.add((a,b));q.append((a,b))
  comps.append((col,cells))
def shape(cells):
 mr=min(r for r,c in cells);mc=min(c for r,c in cells)
 return tuple(sorted((r-mr,c-mc) for r,c in cells))
for i,(col,cells) in enumerate(comps):
 rs=[r for r,c in cells];cs=[c for r,c in cells]
 print(i,col,len(cells),(min(rs),min(cs),max(rs),max(cs)),shape(cells))
